//! Runtime/projector and explicit topology receipts over the current IO actor.
use super::*;use crate::projectors::Action;
impl StudioApp {
 pub(super) fn projector_action(&mut self,action:Action,ctx:&egui::Context){match action{
  Action::SceneVisibility{session,revision,scene,show}=>{if session!=self.session.identity()||self.session.snapshot().revision()!=revision||self.session.snapshot().scene(scene).is_none(){self.message(true,"The Multiview scene changed. Open its menu again.");return;}self.publish_command_at(Some(revision),Command::SetSceneShowInMultiview{scene,show},false);ctx.request_repaint();},
  Action::Open{session,revision,target,monitor,topology}=>{if session!=self.session.identity(){self.message(true,"The projector belongs to another document.");return;}if let Err(error)=self.projectors.open(&self.session,revision,target,monitor,topology,&self._render_gpu,ctx){self.message(true,error);}ctx.request_repaint();},
  Action::Refresh{session}=>{if session!=self.session.identity()||self.io.busy()||self.projectors.pending_monitors.is_some(){self.message(true,"Wait for the active I/O operation before refreshing projector monitors.");return;}match self.io.submit(session,Job::ProjectorMonitors){Ok(())=>self.projectors.pending_monitors=self.io.request(),Err(error)=>self.message(true,error)}},
  Action::Fullscreen{session,revision,window,epoch,monitor,topology}=>{if session!=self.session.identity(){self.message(true,"The projector belongs to another document.");return;}if let Err(error)=self.projectors.fullscreen(&self.session,revision,window,epoch,monitor,topology,ctx){self.message(true,error);}ctx.request_repaint();},
  Action::Problem(error)=>self.message(true,error),
  Action::CloseAll{session}=>{if session==self.session.identity(){self.projectors.close(ctx);}}
 }}
 pub(super) fn projector_completion(&mut self,completion:crate::io::Completion,ctx:&egui::Context)->Option<crate::io::Completion>{
  if self.projectors.restoration.pending.as_ref().is_some_and(|pending|pending.request==completion.request){let pending=self.projectors.restoration.pending.take()?;if completion.session!=pending.prepared.session()||!self.projector_restore_fresh(&pending.prepared){self.message(true,"Saved projector restoration became obsolete; no windows were opened.");return None;}match completion.result{Ok(Reply::ProjectorsResolved(resolved))if resolved.prepared.session()==pending.prepared.session()&&resolved.prepared.revision()==pending.prepared.revision()&&resolved.prepared.saved()==pending.prepared.saved()=>self.projectors.restoration.ready=Some(resolved),Err(error)=>self.message(true,error),_=>self.message(true,"Projector restoration returned an unexpected receipt.")}ctx.request_repaint();return None;}
  if self.projectors.pending_monitors!=Some(completion.request){return Some(completion);}self.projectors.pending_monitors=None;if self.session.is_closed()||completion.session!=self.session.identity(){return None;}let result=match completion.result{Ok(Reply::ProjectorMonitors(monitors))=>Ok(monitors),Err(error)=>Err(error),_=>Err("Projector monitor discovery returned an unexpected receipt.".into())};if let Err(error)=self.projectors.monitors(result){self.message(true,error);}None
 }
 fn projector_restore_fresh(&self,prepared:&skylive_host::projector::restoration::Prepared)->bool{!self.session.is_closed()&&prepared.session()==self.session.identity()&&prepared.revision()==self.session.snapshot().revision()&&prepared.saved()==self.session.snapshot().saved_projectors()&&self.session.snapshot().preferences().projectors().save_windows()}
 pub(super) fn schedule_projector_restoration(&mut self){let model=self.session.snapshot();if !model.preferences().projectors().save_windows()||model.saved_projectors().is_empty(){return;}match skylive_host::projector::restoration::prepare(self.session.identity(),&model){Ok(prepared)=>{self.projectors.restoration.queued=Some(prepared);self.projectors.restoration.preserve_saved=true;},Err(error)=>self.message(true,error.to_string())}}
 pub(super) fn update_projector_restoration(&mut self,ctx:&egui::Context){
  if self.allow_close||self.close_dialog||self.session.is_closed(){return;}
  if let Some(resolved)=self.projectors.restoration.ready.take(){if !self.projector_restore_fresh(&resolved.prepared){self.message(true,"Saved projector restoration became obsolete; no windows were opened.");return;}
   if !resolved.windows.is_empty(){match self.projectors.prepare_worker(&self._render_gpu){Ok(())=>{},Err(skylive_host::projector::Error::Busy)=>{self.projectors.restoration.ready=Some(resolved);if !self.projectors.restoration.waiting_retirement{self.message(false,"Waiting for the previous projector renderer to retire before restoring windows.");self.projectors.restoration.waiting_retirement=true;}ctx.request_repaint_after(std::time::Duration::from_millis(16));return;},Err(error)=>{self.message(true,error.to_string());return;}}}
   let mut problem=!resolved.issues.is_empty();for issue in &resolved.issues{eprintln!("Saved projector restore {:?} index {:?} monitor {:?}: {}",issue.kind,issue.index,issue.monitor,issue.detail);}
   if !resolved.monitors.is_empty(){if let Err(error)=self.projectors.monitors(Ok(resolved.monitors)){self.message(true,error);return;}}else{let _=self.projectors.monitors(Err("Projector monitor discovery is unavailable; using windowed backend placement.".into()));}
   let mut opened=0;for window in resolved.windows{match self.projectors.restore_window(&self.session,resolved.prepared.revision(),window,&self._render_gpu,ctx){Ok(())=>opened+=1,Err(error)=>{problem=true;eprintln!("Saved projector route: {error}");self.message(true,error);}}}
   self.projectors.restoration.waiting_retirement=false;self.projectors.restoration.preserve_saved=problem&&opened==0;
   if opened==0{self.message(problem,"No saved projector windows were queued. Unavailable routes remain in the saved collection metadata.");}else{self.message(problem,crate::status::Status::formatted("Saved projector routes queued: {count}. Native windows and video readiness are still pending.",&[("{count}",opened.to_string())]));}ctx.request_repaint();return;
  }
  if self.projectors.restoration.pending.is_some()||self.io.busy()||self.dialog.is_some()||self.documents.modal_open(){return;}
  let Some(prepared)=self.projectors.restoration.queued.take()else{return;};if !self.projector_restore_fresh(&prepared){self.message(true,"Saved projector restoration became obsolete; no windows were opened.");return;}
  match self.io.submit(self.session.identity(),Job::RestoreProjectors(prepared.clone())){Ok(())=>{if let Some(request)=self.io.request(){self.projectors.restoration.pending=Some(crate::projectors::RestorePending{request,prepared});}else{self.message(true,"Projector restoration has no request identity.");}},Err(error)=>self.message(true,error)}ctx.request_repaint();
 }
 /// Capture exactly the admitted native save boundary; never revise Core on a
 /// geometry tick. The canonical command owns validation and non-Undo metadata.
 pub(super) fn capture_projector_windows(&mut self)->bool{let windows=match self.projectors.saved_windows(&self.session){Ok(value)=>value,Err(error)=>{self.message(true,error);return false;}};let revision=self.session.snapshot().revision();match self.session.apply_at(Some(revision),Command::SetSavedProjectors{windows}){Ok(_)=>true,Err(error)=>{self.message(true,error.to_string());false}}}
 /// Only a previously clean document can be automatically saved on exit.
 /// Existing dirty/discard policy is never bypassed by projector presentation.
 pub(super) fn save_projectors_before_clean_exit(&mut self,ctx:&egui::Context)->bool{if self.io.busy()||self.session.is_closed()||self.session.is_document_dirty()||!self.session.snapshot().preferences().projectors().save_windows(){return false;}let windows=match self.projectors.saved_windows(&self.session){Ok(value)=>value,Err(error)=>{self.message(true,error);return true;}};if &windows==self.session.snapshot().saved_projectors(){return false;}if !self.capture_projector_windows(){return true;}if self.active_document_path.is_some(){self.save(Some(AfterIo::SaveAndClose));}else{self.close_dialog=true;}ctx.request_repaint();true}
}
